export async function postAssetDepreciation(id:string,form:FormData){
 const session=await requireSession();
 assertCapability(session,'finance.asset.manage');
 assertCapability(session,'finance.journal.post');await requireFinance(session,'finance.asset.manage');await transaction(async tx=>{const organisationId=session.organisationId,asset=await tx.financeAsset.findFirstOrThrow({where:{id,organisationId,status:'ACTIVE'}}),postingDate=date(text(form,'date'));if(postingDate<asset.acquiredAt)throw new Error('Depreciation cannot precede acquisition.');const month=postingDate.toISOString().slice(0,7),sourceKey=`depreciation:${id}:${month}`;if(await tx.financeJournal.count({where:{organisationId,sourceKey}}))throw new Error('Depreciation already posted for this month.');const amount=roundRatio(asset.cost-asset.residual,BigInt(asset.lifeMonths)),remaining=asset.cost-asset.residual-asset.accumulated,depreciation=amount>remaining?remaining:amount;if(depreciation<=0n)throw new Error('Asset is fully depreciated.');const a=await controls(tx,organisationId,asset.entityId),entity=await tx.financeEntity.findFirstOrThrow({where:{id:asset.entityId,organisationId}});await postLedger(tx,session,{entityId:asset.entityId,date:postingDate,description:`Depreciation: ${asset.name}`,sourceKey,sourceType:'DEPRECIATION',sourceId:id,currency:entity.currency,rate:'1',lines:[{accountId:a('DEPRECIATION'),description:asset.name,debit:depreciation,credit:0n},{accountId:a('DEPRECIATION_ACCUMULATED'),description:asset.name,debit:0n,credit:depreciation}]});await tx.financeAsset.update({where:{id},data:{accumulated:{increment:depreciation},version:{increment:1}}});});refresh();
}
