 await requireFinance(session,'finance.overview.read');const reason=z.string().min(5).max(2000).parse(text(form,'reason'));await transaction(async tx=>{const doc=await tx.financeDocument.findFirstOrThrow({where:{AND:[documentScope(session),{id,status:{in:['DRAFT','AWAITING_APPROVAL','NEEDS_INFORMATION','REJECTED','APPROVED']},journalId:null}]}});assertCapability(session,documentCapability(doc.kind,true));if(['PO','RECEIPT'].includes(doc.kind))throw new Error('Purchasing cancellation requires receipt/commitment review.');await tx.approvalInstance.updateMany({where:{organisationId:session.organisationId,subjectId:id,status:'PENDING'},data:{status:'CANCELLED'}});await tx.financeDocument.update({where:{id},data:{status:'CANCELLED',duplicateKey:doc.salesOrderId?null:doc.duplicateKey,version:{increment:1}}});await tx.financeTimeline.create({data:{organisationId:session.organisationId,documentId:id,actorUserId:session.userId,action:'VOIDED',detail:reason}});await tx.auditEntry.create({data:{organisationId:session.organisationId,actorUserId:session.userId,action:'finance.draft.voided',entityType:'FinanceDocument',entityId:id,after:{reason}}});});refresh();
